#!/usr/bin/env python3
"""
publish_hardware_suite.py — Automated Open-Hardware Publisher for RegenerativeCompute
Deploys:
  1. hardware.html (Interactive bilingual Open-Hardware Hub: BitTerrarium, BitAquaponics, BitPlant)
  2. hardware/openscad/bitterrarium_topper.scad   (17W Bitaxe Dry Cloche Topper)
  3. hardware/openscad/pico_bitaquaponics.scad    (1.35L Bitaxe Shrimp + Wolffia + Air-Lift)
  4. hardware/openscad/bitplant_manifold.scad     (140W Avalon Nano 3S Hydroponic Manifold)
  5. data/hardware_catalog.json                   (Machine-readable Open-Hardware manifest)
  6. Automatically links hardware.html into index.html navigation if present,
     and optionally compiles STL meshes if `openscad` CLI is installed.
"""

import os
import json
import shutil
import subprocess

SCAD_FILES = {
  "hardware/openscad/bitterrarium_topper.scad": "// ============================================================================\n// BITTERRARIUM v1.0 — 17W BITAXE SNAP-ON DRY CLOCHE BIOSPHERE TOPPER\n// Regenerative Compute (regenerativecompute.org | regenerativecompute.io)\n// Author: Pascal Ranoroarijaona (Ranaora) — Sydney Tech Central (2026)\n// License: CERN-OHL-P v2 / MIT Open Hardware Commons\n// ============================================================================\n// HARDWARE TARGET:\n// - Bitaxe Gamma 601 (PCB: 99.76 x 56.54 x 1.6 mm, BM1370 ASIC, 17W, 40mm fan)\n// - Dish: 150 mm anodized aluminum saucer (1.2 - 1.5 mm thick)\n// - Dome: 150 mm OD borosilicate glass cloche bell jar\n// - Thermal Split: ~35% (~6 Wth) warms Terra Preta moss bed to 27.5°C;\n//   ~65% vents laterally so BM1370 ASIC stays < 54°C.\n// ============================================================================\n\nPART_TO_RENDER = \"assembly\"; // \"assembly\", \"cradle\", \"gutter_ring\", \"led_crown\"\n\npcb_len       = 99.76;\npcb_wid       = 56.54;\npcb_thick     = 1.60;\nclearance     = 0.35;\nsaucer_od     = 150.0;\ncloche_od     = 146.0;\nwall          = 2.4;\ncradle_h      = 50.0;\nbypass_pct    = 65;   // Lateral hot-air bypass % (keeps ASIC cool & moss < 29°C)\n$fn           = 80;\n\nif (PART_TO_RENDER == \"assembly\") {\n    bt_assembly();\n} else if (PART_TO_RENDER == \"cradle\") {\n    bt_cradle();\n} else if (PART_TO_RENDER == \"gutter_ring\") {\n    bt_condensation_gutter();\n} else if (PART_TO_RENDER == \"led_crown\") {\n    bt_led_crown();\n}\n\nmodule bt_cradle() {\n    base_od = saucer_od + 6.0;\n    difference() {\n        union() {\n            // Tapered architectural plinth (Shou-Sugi-Ban / fluted style)\n            cylinder(d1 = base_od + 8, d2 = base_od, h = cradle_h);\n            // Angled front visor for 0.91\" Bitaxe OLED screen\n            translate([0, -base_od/2 + 1, 16])\n                rotate([24, 0, 0])\n                    cube([36, 12, 20], center = true);\n        }\n\n        // Internal warm-air plenum\n        translate([0, 0, wall])\n            cylinder(d1 = base_od - 2*wall, d2 = saucer_od - 8, h = cradle_h + 2);\n\n        // Slide-in Bitaxe Gamma 601 slot from rear (Y+)\n        sw = pcb_wid + 2*clearance;\n        sl = pcb_len + 2*clearance;\n        translate([-sw/2, -sl/2 + 6, 10])\n            cube([sw, sl + 35, 32]);\n        translate([-(sw + 2.4)/2, -sl/2 + 6, 12])\n            cube([sw + 2.4, sl + 35, pcb_thick + 0.5]);\n\n        // Front 0.91\" OLED window\n        translate([0, -base_od/2 - 1, 16])\n            rotate([24, 0, 0])\n                cube([28, 22, 13], center = true);\n\n        // Cool intake louvers (bottom)\n        for (a = [30 : 45 : 330]) {\n            rotate([0, 0, a])\n                translate([base_od/2, 0, 7])\n                    cube([16, 14, 6], center = true);\n        }\n\n        // Lateral thermal bypass exhaust slots (sized by bypass_pct)\n        slot_h = 4.0 + (bypass_pct / 100.0) * 6.0;\n        for (a = [0 : 45 : 315]) {\n            rotate([0, 0, a + 22.5])\n                translate([base_od/2 - 2, 0, cradle_h - 10])\n                    cube([16, 18, slot_h], center = true);\n        }\n\n        // Top seat for 150 mm Anodized Aluminum Saucer\n        translate([0, 0, cradle_h - 3.5])\n            cylinder(d = saucer_od + 0.8, h = 5.0);\n    }\n}\n\n// Internal condensation return ring: catches water droplets rolling down\n// the inside of the glass cloche and channels them into the biochar bed.\nmodule bt_condensation_gutter() {\n    difference() {\n        cylinder(d = saucer_od - 1.0, h = 12.0);\n        translate([0, 0, -1])\n            cylinder(d = cloche_od - 8.0, h = 15.0);\n        // V-groove seat for 146mm borosilicate glass cloche rim\n        translate([0, 0, 5.0])\n            difference() {\n                cylinder(d = cloche_od + 1.2, h = 8.0);\n                cylinder(d = cloche_od - 4.2, h = 8.0);\n            }\n        // 8 inward weep channels directing condensed rain into moss\n        for (a = [0 : 45 : 315]) {\n            rotate([0, 0, a])\n                translate([cloche_od/2 - 3, 0, 5.0])\n                    rotate([0, -25, 0])\n                        cube([10, 3.0, 4.0], center = true);\n        }\n    }\n}\n\nmodule bt_led_crown() {\n    difference() {\n        cylinder(d = 54.0, h = 8.0);\n        translate([0, 0, 2.0]) cylinder(d = 48.0, h = 7.0);\n        translate([0, 0, -1]) cylinder(d = 22.0, h = 10.0);\n    }\n}\n\nmodule bt_assembly() {\n    color(\"#d97706\") bt_cradle();\n    // Aluminum conduction dish\n    color(\"#cbd5e1\") translate([0, 0, cradle_h - 3.0]) cylinder(d = saucer_od, h = 2.0);\n    // Condensation gutter\n    color(\"#334155\") translate([0, 0, cradle_h - 1.0]) bt_condensation_gutter();\n    // Terra Preta Biochar + Moss hemisphere\n    color(\"#1c1917\") translate([0, 0, cradle_h]) cylinder(d = cloche_od - 10, h = 18);\n    color(\"#22c55e\") translate([0, 0, cradle_h + 18]) resize([120, 120, 45]) sphere(d = 100);\n    // Borosilicate Cloche Dome\n    color(\"#e0f2fe\", 0.22)\n        translate([0, 0, cradle_h + 4])\n            difference() {\n                union() {\n                    cylinder(d = cloche_od, h = 75);\n                    translate([0, 0, 75]) sphere(d = cloche_od);\n                }\n                translate([0, 0, -1]) cylinder(d = cloche_od - 4, h = 76);\n                translate([0, 0, 75]) sphere(d = cloche_od - 4);\n                translate([0, 0, -80]) cube([300, 300, 160], center = true);\n            }\n}\n",
  "hardware/openscad/pico_bitaquaponics.scad": "// ============================================================================\n// PICO-BITAQUAPONICS v1.0 — ULTRA-COMPACT BITAXE AQUAPONIC ECOSYSTEM (1.35 L)\n// Regenerative Compute (regenerativecompute.org | regenerativecompute.io)\n// Author: Pascal Ranoroarijaona (Ranaora) — Sydney Tech Central (2026)\n// License: CERN-OHL-P v2 / MIT Open Hardware Commons\n// ============================================================================\n// DIMENSIONS & THERMAL BUDGET:\n// - Target Miner   : Bitaxe Gamma 601 (PCB 99.76 x 56.54 mm, 40x40mm fan, ~17W)\n// - Footprint      : 124 mm x 124 mm x 265 mm total height (fits any desk)\n// - Water Volume   : ~1.35 L freshwater (26.5°C +/- 1°C via adjustable baffle)\n// - Biology        : 3-4 Neocaridina shrimp + 2 Planorbis snails + Terra Preta\n//                    biochar biofilter + Wolffia arrhiza + watercress/mint\n// ============================================================================\n\n/* [Render Selector] */\n// Options: \"assembly\", \"base_cradle\", \"thermal_baffle\", \"hydro_basket\", \"airlift_tube\", \"cloche_ring\"\nPART_TO_RENDER = \"assembly\";\n\n/* [Bitaxe Gamma 601 Exact PCB Parameters (mm)] */\npcb_len         = 99.76;   // Exact Bitaxe Gamma 601 length\npcb_wid         = 56.54;   // Exact Bitaxe Gamma 601 width\npcb_thick       = 1.60;    // FR4 thickness\npcb_clearance   = 0.35;    // Fit tolerance per side\nfan_size        = 40.5;    // 40x40mm fan clearance\ndc_jack_dia     = 9.5;     // 5.5x2.1mm barrel plug opening\noled_win_w      = 28.0;    // Front 0.91\" OLED viewing window width\noled_win_h      = 14.0;    // Front 0.91\" OLED viewing window height\n\n/* [Vessel & Thermal Transfer Plate Parameters (mm)] */\n// Fits standard 115mm OD borosilicate glass jar/beaker (~1.35L, 140mm tall)\nvessel_od       = 115.0;\nvessel_wall     = 2.5;\nvessel_id       = vessel_od - 2 * vessel_wall; // 110.0 mm\nvessel_h        = 135.0;\nalu_plate_dia   = 112.0;   // Anodized aluminum thermal transfer disc\nalu_plate_thick = 1.5;\n\n/* [Print & Structural Settings] */\nwall            = 2.4;\ncradle_h        = 54.0;    // Height of Bitaxe hot-air plenum base\nbaffle_open_pct = 32;      // Default 32% heat coupling (~5.4 Wth into 1.35L water)\n$fn             = 72;\n\n// ============================================================================\n// RENDER DISPATCHER\n// ============================================================================\nif (PART_TO_RENDER == \"assembly\") {\n    full_assembly();\n} else if (PART_TO_RENDER == \"base_cradle\") {\n    part_base_cradle();\n} else if (PART_TO_RENDER == \"thermal_baffle\") {\n    part_thermal_baffle(baffle_open_pct);\n} else if (PART_TO_RENDER == \"hydro_basket\") {\n    part_hydro_basket();\n} else if (PART_TO_RENDER == \"airlift_tube\") {\n    part_airlift_tube();\n} else if (PART_TO_RENDER == \"cloche_ring\") {\n    part_cloche_ring();\n}\n\n// ============================================================================\n// 1. PART A: BITAXE GAMMA 601 HORIZONTAL PLENUM CRADLE\n// ============================================================================\nmodule part_base_cradle() {\n    outer_d = vessel_od + 2 * wall + 4.0; // 123.8 mm cylindrical shell\n\n    difference() {\n        union() {\n            // Main cylindrical thermal chimney shell\n            cylinder(d = outer_d, h = cradle_h);\n\n            // Front angled OLED display visor bezel\n            translate([0, -outer_d/2 + 2, 16])\n                rotate([22, 0, 0])\n                    cube([oled_win_w + 10, 10, oled_win_h + 8], center = true);\n\n            // Anti-tip outrigger feet (4x)\n            for (a = [45 : 90 : 315]) {\n                rotate([0, 0, a])\n                    translate([outer_d/2 - 2, 0, 0])\n                        hull() {\n                            cylinder(d = 12, h = 4);\n                            translate([6, 0, 0]) cylinder(d = 8, h = 3);\n                        }\n            }\n        }\n\n        // Hollow internal plenum chamber\n        translate([0, 0, wall])\n            cylinder(d = outer_d - 2 * wall, h = cradle_h + 1);\n\n        // Horizontal slide-in slot for Bitaxe Gamma 601 PCB (from rear Y+)\n        slot_w = pcb_wid + 2 * pcb_clearance;\n        slot_l = pcb_len + 2 * pcb_clearance;\n        translate([-slot_w/2, -slot_l/2 + 4, 10])\n            cube([slot_w, slot_l + 25, 34]);\n\n        // PCB edge-rail grooves (locks board horizontally)\n        translate([-(slot_w + 2.4)/2, -slot_l/2 + 4, 12])\n            cube([slot_w + 2.4, slot_l + 25, pcb_thick + 0.5]);\n\n        // Rear DC 5.5x2.1mm power barrel & USB/cable pass-through\n        translate([0, outer_d/2, 17])\n            rotate([90, 0, 0])\n                cylinder(d = dc_jack_dia + 3, h = 25, center = true);\n\n        // Front 0.91\" OLED viewing cutout\n        translate([0, -outer_d/2 + 1, 16])\n            rotate([22, 0, 0])\n                cube([oled_win_w, 22, oled_win_h], center = true);\n\n        // Cool air intake vents (bottom perimeter, 8 slots)\n        for (i = [0 : 7]) {\n            rotate([0, 0, i * 45 + 22.5])\n                translate([outer_d/2 - 4, 0, 7])\n                    cube([12, 14, 6], center = true);\n        }\n\n        // Adjustable thermal bypass exhaust vents (upper perimeter)\n        for (i = [0 : 5]) {\n            rotate([0, 0, i * 60])\n                translate([outer_d/2 - 4, 0, cradle_h - 11])\n                    cube([12, 18, 7], center = true);\n        }\n\n        // Top rebate seat for Thermal Baffle & Aluminum Transfer Disc\n        translate([0, 0, cradle_h - 4.0])\n            cylinder(d = vessel_od + 2.4, h = 5.0);\n    }\n\n    // Internal PCB support pillars (4 corners)\n    for (sx = [-1, 1], sy = [-1, 1]) {\n        translate([sx * (pcb_wid/2 - 3), sy * (pcb_len/2 - 5) + 4, wall])\n            cylinder(d = 5.5, h = 10 - wall);\n    }\n}\n\n// ============================================================================\n// 2. PART B: THERMAL BAFFLE & ALUMINUM DISC HOLDER (26.5°C WATER REGULATOR)\n// ============================================================================\n// Controls what fraction of the 17W ASIC plume hits the aluminum tank bottom\n// vs. venting laterally. Default 32% open -> ~5.4 Wth -> steady 26.5°C water.\nmodule part_thermal_baffle(open_pct = 32) {\n    ring_od = vessel_od + 2.0;\n    ring_h  = 9.0;\n\n    difference() {\n        union() {\n            // Outer retaining collar that holds the borosilicate glass vessel\n            cylinder(d = ring_od + 3.2, h = ring_h);\n        }\n\n        // Upper socket for glass vessel (4.5 mm deep)\n        translate([0, 0, ring_h - 4.5])\n            cylinder(d = vessel_od + 0.6, h = 5.5);\n\n        // Seat for 112mm Anodized Aluminum Thermal Transfer Plate\n        translate([0, 0, ring_h - 4.5 - alu_plate_thick])\n            cylinder(d = alu_plate_dia + 0.5, h = alu_plate_thick + 0.5);\n\n        // Central thermal aperture (scaled by open_pct)\n        ap_dia = (alu_plate_dia - 14) * sqrt(open_pct / 100.0);\n        translate([0, 0, -1])\n            cylinder(d = max(18, ap_dia), h = ring_h + 2);\n\n        // Radial warm-air bypass channels under the plate\n        for (a = [0 : 60 : 300]) {\n            rotate([0, 0, a])\n                translate([alu_plate_dia/2 - 6, 0, 1.8])\n                    cube([16, 12, 3.6], center = true);\n        }\n    }\n}\n\n// ============================================================================\n// 3. PART C: ZERO-CLOG 3D-PRINTED AIR-LIFT WATER PUMP & OXYGENATOR\n// ============================================================================\n// Uses a tiny 1.2W 5V USB air pump to lift nitrate-rich water from the\n// shrimp/biochar floor up into the top plant basket while oxygenating water.\nmodule part_airlift_tube() {\n    tube_od = 10.0;\n    tube_id = 6.8;\n    lift_h  = vessel_h - 14.0;\n\n    difference() {\n        union() {\n            // Intake strainer foot resting in LECA/Biochar bed\n            cylinder(d = 18.0, h = 10.0);\n            // Vertical riser pipe\n            cylinder(d = tube_od, h = lift_h);\n            // Air-line barb inlet at z = 14 mm\n            translate([tube_od/2 - 1, 0, 14])\n                rotate([0, 90, 0])\n                    cylinder(d1 = 5.2, d2 = 4.2, h = 8.0);\n            // Top gooseneck spout discharging into Hydro Basket\n            translate([0, 0, lift_h])\n                rotate([0, -65, 0])\n                    cylinder(d = tube_od, h = 24.0);\n        }\n\n        // Main internal water riser bore\n        translate([0, 0, 2.0])\n            cylinder(d = tube_id, h = lift_h + 2);\n\n        // Gooseneck bore\n        translate([0, 0, lift_h])\n            rotate([0, -65, 0])\n                cylinder(d = tube_id, h = 26.0);\n\n        // Air injection nozzle bore\n        translate([0, 0, 14])\n            rotate([0, 90, 0])\n                cylinder(d = 2.2, h = 16.0);\n\n        // Bottom shrimp-safe intake slots (1.5 mm wide so baby shrimp stay safe!)\n        for (a = [0 : 45 : 315]) {\n            rotate([0, 0, a])\n                translate([6.5, 0, 4.5])\n                    cube([8, 1.5, 5.0], center = true);\n        }\n    }\n}\n\n// ============================================================================\n// 4. PART D: UPPER HYDROPONIC + WOLFFIA BASKET (NITRATE BIO-FILTER)\n// ============================================================================\nmodule part_hydro_basket() {\n    basket_od = vessel_id - 1.2; // 108.8 mm slips smoothly inside glass rim\n    basket_h  = 34.0;\n    lip_od    = vessel_od + 2.0;\n\n    difference() {\n        union() {\n            // Top resting rim on glass vessel edge\n            translate([0, 0, basket_h - 3.0])\n                cylinder(d = lip_od, h = 3.0);\n\n            // Submerged root & Terra Preta cup body\n            cylinder(d = basket_od, h = basket_h);\n\n            // Central standpipe overflow weir (controls water level in basket)\n            translate([-22, 0, 0])\n                cylinder(d = 14.0, h = basket_h - 6.0);\n        }\n\n        // Hollow plant & Wolffia basin\n        translate([0, 0, 2.2])\n            cylinder(d = basket_od - 4.0, h = basket_h);\n\n        // Overflow return drain bore\n        translate([-22, 0, -1])\n            cylinder(d = 9.5, h = basket_h);\n\n        // Pass-through notch on rim for Air-Lift gooseneck & 5V LED cable\n        translate([basket_od/2 - 4, 0, basket_h - 10])\n            cylinder(d = 13.0, h = 14.0);\n\n        // Root aeration & nutrient percolation slots on floor\n        for (r = [14, 26, 38]) {\n            n_holes = floor(r * 0.45);\n            for (k = [0 : n_holes - 1]) {\n                rotate([0, 0, k * (360 / n_holes)])\n                    translate([r, 0, -1])\n                        cylinder(d = 3.2, h = 5.0);\n            }\n        }\n    }\n}\n\n// ============================================================================\n// 5. PART E: TOP BIOSPHERE CLOCHE RING & LED HOLDER\n// ============================================================================\nmodule part_cloche_ring() {\n    ring_od = vessel_od + 3.0;\n    difference() {\n        cylinder(d = ring_od, h = 14.0);\n        // Bottom seat onto hydro basket lip\n        translate([0, 0, -1])\n            cylinder(d = vessel_od + 0.6, h = 7.0);\n        // Top groove for borosilicate glass dome / cloche\n        translate([0, 0, 8.0])\n            cylinder(d = vessel_od + 0.8, h = 7.0);\n        // Central light & gas-exchange aperture\n        translate([0, 0, -1])\n            cylinder(d = vessel_id - 6.0, h = 16.0);\n        // 4 micro gas-exchange breathing ports (prevents CO2 starvation)\n        for (a = [0 : 90 : 270]) {\n            rotate([0, 0, a + 45])\n                translate([ring_od/2, 0, 7.0])\n                    rotate([0, 90, 0])\n                        cylinder(d = 3.0, h = 10.0, center = true);\n        }\n    }\n}\n\n// ============================================================================\n// FULL EXPLODED / ASSEMBLED VISUALIZATION\n// ============================================================================\nmodule full_assembly() {\n    // 1. Bitaxe Cradle Base\n    color(\"#2b211a\") part_base_cradle();\n\n    // 2. Simulated Bitaxe Gamma 601 PCB + Heatsink inside Cradle\n    color(\"#111827\")\n        translate([0, 4, 12.5])\n            cube([pcb_wid, pcb_len, pcb_thick], center = true);\n    color(\"#f7931a\")\n        translate([0, 4, 24])\n            cube([fan_size, fan_size, 20], center = true);\n\n    // 3. Thermal Baffle + Aluminum Transfer Disc\n    color(\"#475569\")\n        translate([0, 0, cradle_h - 3.5])\n            part_thermal_baffle(baffle_open_pct);\n    color(\"#cbd5e1\")\n        translate([0, 0, cradle_h + 0.5])\n            cylinder(d = alu_plate_dia, h = alu_plate_thick);\n\n    // 4. Transparent 1.35L Borosilicate Vessel + Water + Biochar Floor\n    color(\"#1c1917\")\n        translate([0, 0, cradle_h + 2.5])\n            cylinder(d = vessel_id - 1, h = 16); // Terra Preta + LECA biofilter\n    color(\"#00ccff\", 0.28)\n        translate([0, 0, cradle_h + 18.5])\n            cylinder(d = vessel_id - 1, h = vessel_h - 34); // 26.5°C Water\n    color(\"#e0f2fe\", 0.22)\n        translate([0, 0, cradle_h + 2.0])\n            difference() {\n                cylinder(d = vessel_od, h = vessel_h);\n                translate([0, 0, -1]) cylinder(d = vessel_id, h = vessel_h + 2);\n            }\n\n    // 5. Air-Lift Riser Tube\n    color(\"#38bdf8\")\n        translate([vessel_id/2 - 11, 0, cradle_h + 4])\n            part_airlift_tube();\n\n    // 6. Upper Hydroponic + Wolffia Basket\n    color(\"#1e293b\")\n        translate([0, 0, cradle_h + vessel_h - 31])\n            part_hydro_basket();\n\n    // 7. Living Greenery (Wolffia mat + emerging herbs)\n    color(\"#44ee77\")\n        translate([0, 0, cradle_h + vessel_h - 2])\n            cylinder(d = vessel_id - 8, h = 3.5);\n    color(\"#22c55e\")\n        translate([12, 0, cradle_h + vessel_h + 15])\n            sphere(d = 34);\n\n    // 8. Top Cloche Ring & Dome\n    color(\"#334155\")\n        translate([0, 0, cradle_h + vessel_h + 1])\n            part_cloche_ring();\n    color(\"#f8fafc\", 0.18)\n        translate([0, 0, cradle_h + vessel_h + 10])\n            difference() {\n                sphere(d = vessel_od);\n                translate([0, 0, -vessel_od]) cube([vessel_od*2, vessel_od*2, vessel_od*2], center = true);\n                sphere(d = vessel_id);\n            }\n}\n",
  "hardware/openscad/bitplant_manifold.scad": "// ============================================================================\n// BITPLANT v1.0 — CANAAN AVALON NANO 3S (140W) HYDROPONIC THERMAL MANIFOLD\n// Regenerative Compute (regenerativecompute.org | regenerativecompute.io)\n// Author: Pascal Ranoroarijaona (Ranaora) — Sydney Tech Central (2026)\n// License: CERN-OHL-P v2 / MIT Open Hardware Commons\n// ============================================================================\n// EXACT HARDWARE SPECS:\n// - Canaan Avalon Nano 3S: 205.0 x 115.0 x 58.5 mm, 6 TH/s, 140W, 33-40 dB\n// - Outlet Exhaust Shroud -> Rotary Summer/Winter Damper -> 100mm Duct Spigot\n// - Feeds warm air (42-48°C) under AC Infinity 72-Cell Dome / NFT Hydro Tray\n//   or pre-dries agricultural biomass for Terra Preta Biochar!\n// ============================================================================\n\nPART_TO_RENDER = \"assembly\"; // \"assembly\", \"exhaust_hood\", \"rotary_damper\", \"tray_diffuser\"\n\nnano_w        = 205.0;   // Exact Avalon Nano 3S width\nnano_d        = 115.0;   // Exact Avalon Nano 3S depth\nnano_h        = 58.5;    // Exact Avalon Nano 3S height\nfit_tol       = 0.60;    // Slip-on gasket clearance\nwall          = 2.6;\nhood_depth    = 36.0;    // Overlap onto Nano 3S exhaust face\ntransition_l  = 95.0;    // Aerodynamic transition to 100mm round duct\nduct_od       = 99.0;    // Fits standard 100mm (4\") insulated flex duct\ndamper_angle  = 20;      // 0 deg = 100% to Hydroponics | 90 deg = Summer Bypass\n$fn           = 72;\n\nif (PART_TO_RENDER == \"assembly\") {\n    bp_assembly();\n} else if (PART_TO_RENDER == \"exhaust_hood\") {\n    bp_exhaust_hood();\n} else if (PART_TO_RENDER == \"rotary_damper\") {\n    bp_rotary_damper();\n} else if (PART_TO_RENDER == \"tray_diffuser\") {\n    bp_tray_diffuser();\n}\n\n// Part A: Aerodynamic Collector Hood snapping onto Avalon Nano 3S exhaust\nmodule bp_exhaust_hood() {\n    in_w = nano_w + 2 * fit_tol;\n    in_h = nano_h + 2 * fit_tol;\n    out_w = in_w + 2 * wall;\n    out_h = in_h + 2 * wall;\n\n    difference() {\n        union() {\n            // Rectangular slip-on collar around Avalon Nano 3S\n            translate([-out_w/2, -out_h/2, 0])\n                cube([out_w, out_h, hood_depth]);\n\n            // Smooth lofted transition from 205x58.5mm rectangle to 100mm circle\n            hull() {\n                translate([-out_w/2, -out_h/2, hood_depth - 1])\n                    cube([out_w, out_h, 1]);\n                translate([0, 0, hood_depth + transition_l])\n                    cylinder(d = duct_od + 2*wall, h = 1);\n            }\n\n            // 100mm Duct Spigot Collar + Summer Bypass T-Branch\n            translate([0, 0, hood_depth + transition_l])\n                cylinder(d = duct_od, h = 42.0);\n\n            // Lateral Summer Bypass Exhaust Port (Ø70mm)\n            translate([0, 0, hood_depth + transition_l + 20])\n                rotate([-90, 0, 0])\n                    cylinder(d = 70.0, h = 62.0);\n\n            // DS18B20 Temperature Sensor Boss (12mm port)\n            translate([duct_od/2 - 2, 0, hood_depth + transition_l + 18])\n                rotate([0, 90, 0])\n                    cylinder(d = 14.0, h = 12.0);\n        }\n\n        // Hollow slip-on pocket for Nano 3S chassis\n        translate([-in_w/2, -in_h/2, -1])\n            cube([in_w, in_h, hood_depth + 1]);\n\n        // Internal aerodynamic loft cavity\n        hull() {\n            translate([-(in_w - 4)/2, -(in_h - 4)/2, hood_depth - 0.5])\n                cube([in_w - 4, in_h - 4, 1]);\n            translate([0, 0, hood_depth + transition_l + 0.5])\n                cylinder(d = duct_od - 2*wall, h = 1);\n        }\n\n        // Main 100mm duct bore\n        translate([0, 0, hood_depth + transition_l - 1])\n            cylinder(d = duct_od - 2*wall, h = 46.0);\n\n        // Summer bypass bore\n        translate([0, 0, hood_depth + transition_l + 20])\n            rotate([-90, 0, 0])\n                cylinder(d = 65.0, h = 66.0);\n\n        // Damper axle shaft holes (6.2mm)\n        translate([0, 0, hood_depth + transition_l + 20])\n            rotate([0, 90, 0])\n                cylinder(d = 6.2, h = duct_od + 20, center = true);\n\n        // DS18B20 probe bore (6.5mm)\n        translate([duct_od/2 - 8, 0, hood_depth + transition_l + 18])\n            rotate([0, 90, 0])\n                cylinder(d = 6.5, h = 24.0);\n    }\n}\n\n// Part B: Butterfly / Rotary Thermal Damper Valve\nmodule bp_rotary_damper() {\n    disc_d = duct_od - 2*wall - 1.6;\n    union() {\n        cylinder(d = disc_d, h = 2.4, center = true);\n        rotate([0, 90, 0])\n            cylinder(d = 5.8, h = duct_od + 26, center = true);\n        // External thumb dial lever\n        translate([duct_od/2 + 12, 0, 0])\n            cube([4, 24, 8], center = true);\n    }\n}\n\n// Part C: Under-Tray Warm Air Diffuser Plenum (fits 540x280mm 72-cell Hydro Tray)\nmodule bp_tray_diffuser() {\n    plenum_w = 240.0; // Modular half-tray diffuser block (print 1 or 2)\n    plenum_l = 240.0;\n    plenum_h = 48.0;\n\n    difference() {\n        union() {\n            translate([-plenum_w/2, -plenum_l/2, 0])\n                cube([plenum_w, plenum_l, plenum_h]);\n            // 100mm inlet collar on side\n            translate([0, -plenum_l/2, plenum_h/2])\n                rotate([90, 0, 0])\n                    cylinder(d = duct_od, h = 28.0);\n        }\n        translate([-(plenum_w - 2*wall)/2, -(plenum_l - 2*wall)/2, wall])\n            cube([plenum_w - 2*wall, plenum_l - 2*wall, plenum_h - 2*wall]);\n\n        // Side inlet bore\n        translate([0, -plenum_l/2 + 4, plenum_h/2])\n            rotate([90, 0, 0])\n                cylinder(d = duct_od - 2*wall, h = 36.0);\n\n        // Top even-heat distribution matrix (keeps root zone uniform at 25°C)\n        for (gx = [-85 : 34 : 85], gy = [-85 : 34 : 85]) {\n            translate([gx, gy, plenum_h - wall - 1])\n                cylinder(d = 12.0, h = wall + 3);\n        }\n\n        // Bottom 6mm condensate drain weep hole\n        translate([plenum_w/2 - 15, plenum_l/2 - 15, -1])\n            cylinder(d = 6.0, h = wall + 3);\n    }\n}\n\nmodule bp_assembly() {\n    // Simulated Avalon Nano 3S Miner Body\n    color(\"#1e293b\")\n        translate([-nano_w/2, -nano_h/2, -nano_d + hood_depth - 5])\n            cube([nano_w, nano_h, nano_d]);\n\n    // Exhaust Manifold Hood\n    color(\"#f7931a\") bp_exhaust_hood();\n\n    // Rotary Damper inside Manifold\n    color(\"#44ee77\")\n        translate([0, 0, hood_depth + transition_l + 20])\n            rotate([damper_angle, 0, 0])\n                bp_rotary_damper();\n\n    // Under-Tray Hydroponic Diffuser (shown offset above)\n    color(\"#0ea5e9\", 0.85)\n        translate([0, 0, hood_depth + transition_l + 95])\n            bp_tray_diffuser();\n}\n"
}

