def patch_index_navigation(index_path="index.html"):
    if not os.path.exists(index_path):
        print("[INFO] index.html not found in current directory; skipping nav injection.")
        return
    with open(index_path, "r", encoding="utf-8") as f:
        html = f.read()
    if 'href="hardware.html"' in html:
        print("[OK] hardware.html link already present in index.html.")
        return
    target = '<div class="nav-links">'
    link_snippet = (
        '<div class="nav-links">\n'
        '        <a href="hardware.html" style="color:var(--sun-gold);font-weight:800;">'
        '<span lang="en">Open Hardware</span><span lang="fr">Plans 3D</span></a>'
    )
    if target in html:
        html = html.replace(target, link_snippet, 1)
        with open(index_path, "w", encoding="utf-8") as f:
            f.write(html)
        print("[OK] Injected Open Hardware link into index.html navigation bar.")

def maybe_compile_stls():
    openscad_bin = shutil.which("openscad")
    if not openscad_bin:
        print("[INFO] OpenSCAD CLI not detected locally; skipping automatic .stl mesh export.")
        return
    os.makedirs("hardware/stl", exist_ok=True)
    jobs = [
        ("hardware/openscad/bitterrarium_topper.scad", "cradle", "hardware/stl/bitterrarium_cradle.stl"),
        ("hardware/openscad/bitterrarium_topper.scad", "gutter_ring", "hardware/stl/bitterrarium_gutter_ring.stl"),
        ("hardware/openscad/pico_bitaquaponics.scad", "base_cradle", "hardware/stl/bitaquaponics_base_cradle.stl"),
        ("hardware/openscad/pico_bitaquaponics.scad", "thermal_baffle", "hardware/stl/bitaquaponics_thermal_baffle.stl"),
        ("hardware/openscad/pico_bitaquaponics.scad", "airlift_tube", "hardware/stl/bitaquaponics_airlift_tube.stl"),
        ("hardware/openscad/pico_bitaquaponics.scad", "hydro_basket", "hardware/stl/bitaquaponics_hydro_basket.stl"),
        ("hardware/openscad/bitplant_manifold.scad", "exhaust_hood", "hardware/stl/bitplant_exhaust_hood.stl"),
        ("hardware/openscad/bitplant_manifold.scad", "tray_diffuser", "hardware/stl/bitplant_tray_diffuser.stl"),
    ]
    for scad_path, part, out_stl in jobs:
        subprocess.run([openscad_bin, "-o", out_stl, "-D", f'PART_TO_RENDER="{part}"', scad_path], check=False)
        print(f"[STL] Exported {out_stl}")

def main():
    os.makedirs("hardware/openscad", exist_ok=True)
    os.makedirs("data", exist_ok=True)

    for rel_path, content in SCAD_FILES.items():
        with open(rel_path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"[OK] Wrote {rel_path}")

    with open("data/hardware_catalog.json", "w", encoding="utf-8") as f:
        json.dump(CATALOG, f, indent=2, ensure_ascii=False)
    print("[OK] Wrote data/hardware_catalog.json")

    patch_index_navigation("index.html")
    maybe_compile_stls()
    print("\nDone! Commit hardware.html, hardware/, data/hardware_catalog.json, and index.html to GitHub Pages.")

if __name__ == "__main__":
    main()
